def solve(g):
    H,W=len(g),len(g[0])
    s=[None]*W
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v!=0:
                k=j if j>=i else j+1
                if s[k%W] is not None and s[k%W]!=v: print("conflict",i,j,k)
                s[k%W]=v
    # fill missing by smallest period consistent with known
    for p in range(1,W+1):
        if W%p==0 and all(s[j] is None or s[j]==s[j%p if j%p<W else j] for j in range(W)) and all(s[j] is not None or s[(j+p)%W] is not None for j in range(W)):
            break
    p=min(p,W)
    base=[s[j] if s[j] is not None else s[(j+p)%W] for j in range(W)]
    s=[base[j%p] for j in range(W)]
    return [[(s[(j+1)%W] if j<i else s[j%W]) if v==0 else v for j,v in enumerate(row)] for i,row in enumerate(g)]
